// 阶段2课程数据（第14-26周），由 H5 版自动提取
module.exports = [{"w":14,"p":2,"theme":"旅行与假日（现在完成时）","d":[{"t":"假日与出国","obj":"学会谈假期，掌握现在完成时入门","time":"45分钟","v":[{"w":"holiday","m":"假日；假期","p":"n.","e":"We had a wonderful holiday in Hainan."},{"w":"vacation","m":"休假（美式）","p":"n.","e":"I am on vacation next week."},{"w":"festival","m":"节日","p":"n.","e":"The Spring Festival is my favorite."},{"w":"trip","m":"旅行；行程","p":"n.","e":"The business trip went well."},{"w":"abroad","m":"在国外","p":"adv.","e":"I have never been abroad before."}],"g":{"t":"现在完成时入门（have/has + done）","exp":"表示“到现在为止”的经历或结果：I have visited Beijing.（我去过北京——对现在的影响：我有这个经历了。）结构：have/has + 动词过去分词。过去分词：visit→visited, go→gone, see→seen。与过去时的区别下周展开。","ex":["I have been to Shanghai twice.","She has visited three countries.","We have finished the report."]},"pr":"1) 用现在完成时写5句自己去过的地方/做过的事。2) 写3句否定（还没做过的事）。3) 口头回答：Have you ever been abroad?","tip":"现在完成时是雅思第一高分语法点。从今天起，所有“我去过/我做过”都用have done说。"},{"t":"旅行体验","obj":"掌握already/yet/just等完成时标志词","time":"45分钟","v":[{"w":"sightseeing","m":"观光","p":"n.","e":"We went sightseeing in the old town."},{"w":"explore","m":"探索","p":"v.","e":"We spent the day exploring the city."},{"w":"destination","m":"目的地","p":"n.","e":"What is your dream destination?"},{"w":"guide","m":"导游；指南","p":"n.","e":"The tour guide was very funny."},{"w":"souvenir","m":"纪念品","p":"n.","e":"I bought some souvenirs for friends."}],"g":{"t":"already / yet / just（完成时信号词）","exp":"already（已经）用于肯定句：I have already packed. yet（还）用于否定疑问：I haven't packed yet. just（刚刚）：We have just arrived. 三个词一出，必是完成时。","ex":["I have just finished my homework.","Have you booked the hotel yet?","She has already left."]},"pr":"1) 用already/yet/just各造2句（现在完成时）。2) 写5句旅行准备进度（护照办了吗？票订了吗？）。3) 口头描述：你最近一次出游的行程。","tip":"听力里just already这类词就是“时态路标”，听到它们立刻反应：完成时来了，填空注意过去分词拼写。"},{"t":"住宿经历","obj":"掌握ever/never，学会问经历","time":"45分钟","v":[{"w":"check in","m":"办理入住","p":"phr.v.","e":"We checked in at three o'clock."},{"w":"check out","m":"退房","p":"phr.v.","e":"What time do we check out tomorrow?"},{"w":"reserve","m":"预订","p":"v.","e":"I have reserved a double room."},{"w":"guest","m":"客人；房客","p":"n.","e":"The hotel is full of guests."},{"w":"view","m":"景色；观点","p":"n.","e":"Our room has a sea view."}],"g":{"t":"ever / never（问经历和否定经历）","exp":"问经历：Have you ever been to Japan? 否定经历：I have never traveled by ship. 回答：Yes, I have. / No, I never have. 或No, I haven't.","ex":["Have you ever stayed in a five-star hotel?","I have never seen the sea in winter.","Have you ever lost your luggage?"]},"pr":"1) 用Have you ever...?写5个问题问家人。2) 写自己的5个“第一次”经历（完成时）。3) 写一段入住酒店对话（10句）。","tip":"Have you ever...是口语Part 1高频句型，也最能自然带出完成时。回答后记得加一句扩展。"},{"t":"旅途状况","obj":"分清完成时和过去时","time":"45分钟","v":[{"w":"delay","m":"延误","p":"v./n.","e":"Our flight was delayed for two hours."},{"w":"cancel","m":"取消","p":"v.","e":"They canceled the meeting."},{"w":"miss","m":"错过；想念","p":"v.","e":"We nearly missed the train."},{"w":"complain","m":"抱怨","p":"v.","e":"He complained about the food."},{"w":"luggage","m":"行李","p":"n.","e":"My luggage didn't arrive."}],"g":{"t":"现在完成时 vs 一般过去时","exp":"黄金法则：有具体过去时间（yesterday, in 2020, last week）用过去时；强调对现在的影响或无具体时间用完成时。对比：I lost my luggage（过去丢的，陈述）/ I have lost my luggage（丢了——现在还没有！）。","ex":["I have lost my passport!","I lost my phone last year.","She has just called the hotel."]},"pr":"1) 翻译10句（判断完成时还是过去时）。2) 写一段投诉经历（过去时叙述+完成时影响）。3) 口头描述一次糟糕的旅行经历。","tip":"考试写作里时态混用是5分和6.5的分界线。每次写完先检查：过去的事，时态统一了吗？"},{"t":"讲旅行故事","obj":"学会生动讲述经历","time":"45分钟","v":[{"w":"adventure","m":"冒险；奇遇","p":"n.","e":"The trip became a real adventure."},{"w":"amazing","m":"令人惊叹的","p":"adj.","e":"The sunset was amazing."},{"w":"experience","m":"经历；体验","p":"n./v.","e":"It was an unforgettable experience."},{"w":"memory","m":"回忆；记忆","p":"n.","e":"I keep many good memories of the trip."},{"w":"unforgettable","m":"难忘的","p":"adj.","e":"The journey was unforgettable."}],"g":{"t":"when / while 引导的叙述（讲故事句型）","exp":"讲故事两连招：when（点时间）：When we arrived, it was raining. while（段时间）：While we waited, we made some friends. 故事结构：背景（进行时）+事件（过去时）+影响（完成时）。","ex":["When we got to the hotel, our room was not ready.","While we were waiting, we met a friendly couple.","The trip has changed my view of travel."]},"pr":"1) 写一次难忘旅行（80词：背景+事件+感受+影响）。2) 把5个新词全部用进去。3) 录音讲述这个故事（90秒）。","tip":"口语Part 2讲经历题（a journey you enjoyed）= 今天的故事结构。直接套：背景→事件→高潮→感受。"}],"sun":{"t":"第14周自检：旅行与完成时","obj":"检验现在完成时和旅行词汇","pr":"1) 听写本周25词。2) 时态专项20题（完成时vs过去时）。3) 口语模拟：Describe a place you have visited（笔记+录音90秒）。4) 复习第1-13周错词（滚动复习开始）。","tip":"从本周起进入阶段二，每周日要加“滚动复习”：随机抽旧词10个+旧语法点1个，遗忘曲线才开始被你打败。"}},{"w":15,"p":2,"theme":"教育与学校生活","d":[{"t":"教育阶段","obj":"学会谈各教育阶段，掌握过去进行时","time":"45分钟","v":[{"w":"primary","m":"初等的；小学的","p":"adj.","e":"My daughter is in primary school."},{"w":"secondary","m":"中等的；中学的","p":"adj.","e":"Secondary education lasts six years."},{"w":"university","m":"大学","p":"n.","e":"She hopes to go to university."},{"w":"graduate","m":"毕业；毕业生","p":"v./n.","e":"He graduated from high school in 2018."},{"w":"degree","m":"学位；程度","p":"n.","e":"She is studying for a master's degree."}],"g":{"t":"过去进行时（was/were + doing）","exp":"过去某时正在进行的动作：I was studying at 8 pm yesterday. 常和when搭配：I was sleeping when you called.（你打电话时我正睡觉。）故事感极强。","ex":["I was doing my homework when he arrived.","We were living in Chengdu at that time.","What were you doing at nine last night?"]},"pr":"1) 写5句昨晚某时刻正在做的事。2) 用when+过去进行写3个“被打断”的故事。3) 口头描述自己中学时代的一天。","tip":"口语讲过去经历时，was doing比did更细腻：I was preparing for the exam.（我当时正在备考。）"},{"t":"课程与讲座","obj":"学会大学课程词汇，掌握while/when","time":"45分钟","v":[{"w":"subject","m":"科目；主题","p":"n.","e":"What subjects are you taking?"},{"w":"course","m":"课程","p":"n.","e":"This course lasts 12 weeks."},{"w":"major","m":"专业；主修","p":"n./v.","e":"Her major is computer science."},{"w":"lecture","m":"讲座；大课","p":"n.","e":"The lecture starts at 9 sharp."},{"w":"seminar","m":"研讨课","p":"n.","e":"We discuss in small seminars."}],"g":{"t":"while vs when（两个“当”）","exp":"while后接延续动词（进行时常见）：While I was listening to the lecture, I took notes. when后可接瞬间动词：When the bell rang, we left. 口诀：while配“长事”，when配“短事”。","ex":["While we were waiting, the professor arrived.","When I got home, Mom was cooking.","I fell asleep while reading."]},"pr":"1) 用while/when各写3句（含过去进行时）。2) 描述自己最难忘的一门课（5句）。3) 口头回答：What was your favorite subject at school?","tip":"课程词汇是听力Section 3-4（校园讨论/讲座）的门票，大学场景词汇从这周开始铺开。"},{"t":"学习方法","obj":"学会谈学习方法，掌握不定式表目的","time":"45分钟","v":[{"w":"memorize","m":"记住；背","p":"v.","e":"It is hard to memorize all these words."},{"w":"understand","m":"理解","p":"v.","e":"I finally understood the grammar."},{"w":"concentrate","m":"集中注意力","p":"v.","e":"I can't concentrate in noisy rooms."},{"w":"take notes","m":"记笔记","p":"phr.","e":"Take notes while you listen."},{"w":"review","m":"复习","p":"v./n.","e":"Review the lesson before bed."}],"g":{"t":"不定式表目的（to do）","exp":"表达“为了做某事”：I get up early to review words.（早起是为了背词。）疑问词+不定式：I don't know how to spell it. 学习方法话题的三件套：目的（to do）+方式（by doing）+频率（how often）。","ex":["I read English aloud to practice pronunciation.","She learns by watching movies.","I review words three times a day."]},"pr":"1) 用to do表目的写5句自己的学习方法。2) 用by doing写3句学习方式。3) 口头介绍：My way of learning English（60秒）。","tip":"by doing（通过做某事）是口语回答How do you...?的万能开头：By watching English videos."},{"t":"校园活动","obj":"学会谈课外活动，掌握动名词作宾语","time":"45分钟","v":[{"w":"club","m":"社团；俱乐部","p":"n.","e":"I joined the English club."},{"w":"activity","m":"活动","p":"n.","e":"There are many activities after class."},{"w":"compete","m":"竞争；比赛","p":"v.","e":"Our team competed with ten schools."},{"w":"volunteer","m":"志愿者","p":"n./v.","e":"She volunteers at the library."},{"w":"society","m":"社团；社会","p":"n.","e":"I am a member of the music society."}],"g":{"t":"动名词作宾语（enjoy/finish/mind/keep doing）","exp":"部分动词后只能接doing：enjoy, finish, mind, keep, practice, suggest, avoid：I enjoy joining clubs. 完成时后也接doing：Have you finished writing? 口诀背下来。","ex":["I enjoy taking part in activities.","Have you finished doing your homework?","Would you mind opening the window?"]},"pr":"1) 用动词+doing写5句校园活动。2) 对比to do表目的造3句。3) 口头回答：Did you take part in any activities at school?","tip":"enjoy/finish/mind doing是高频考点，写作里写错enjoy to do直接扣语法分。"},{"t":"教育观点","obj":"学会表达教育观点，掌握stop to do vs stop doing","time":"45分钟","v":[{"w":"educate","m":"教育","p":"v.","e":"It takes a village to educate a child."},{"w":"knowledge","m":"知识","p":"n.","e":"Knowledge is power."},{"w":"skill","m":"技能","p":"n.","e":"Learning needs both knowledge and skills."},{"w":"useful","m":"有用的","p":"adj.","e":"Is this knowledge useful for the future?"},{"w":"important","m":"重要的","p":"adj.","e":"Education is important for everyone."}],"g":{"t":"stop to do vs stop doing & forget/remember to do","exp":"stop doing=停止正在做的事：stop talking（别说话了）。stop to do=停下来去做另一件事：stop to rest（停下来休息）。同理remember to do（记得要去做）vs remember doing（记得做过）。","ex":["We stopped talking when the teacher came in.","After two hours, we stopped to have a break.","I remembered to bring my ID card."]},"pr":"1) 用stop to do/stop doing各造3句。2) 写一段“我心中的好教育”（80词，用上至少2个动名词）。3) 口语讨论：Is homework useful?","tip":"stop doing和stop to do意思相反，是听力判断题的迷你陷阱，写作里用对是语法加分项。"}],"sun":{"t":"第15周自检：教育话题","obj":"检验过去进行时、不定式和动名词","pr":"1) 听写本周25词。2) 语法专项20题（while/when、to do/doing）。3) 口语模拟：Describe a teacher who influenced you（90秒录音）。4) 滚动复习：抽第1-14周旧词15个。","tip":"教育话题是雅思写作和口语的常青树，本周期末把教育相关词汇攒起来，就是你的第一批话题弹药库。"}},{"w":16,"p":2,"theme":"城市与乡村","d":[{"t":"城市场所","obj":"学会城市词汇，掌握定语从句入门","time":"45分钟","v":[{"w":"downtown","m":"市中心","p":"n./adv.","e":"I work downtown."},{"w":"suburb","m":"郊区","p":"n.","e":"They moved to the suburbs last year."},{"w":"district","m":"区域；行政区","p":"n.","e":"The tech district is in the south."},{"w":"square","m":"广场","p":"n.","e":"People dance in the square at night."},{"w":"landmark","m":"地标","p":"n.","e":"The tower is the city's landmark."}],"g":{"t":"定语从句入门（who / which / that）","exp":"把两句合成一句：I know a man. + He works downtown. → I know a man who works downtown.（我认识一个在市中心工作的人。）人用who，物用which，that两者通用。写作从“简单句选手”升级为“复合句选手”的第一步。","ex":["I live in a city which has many parks.","She is the friend who helped me most.","This is the building that was built in 1930."]},"pr":"1) 用定语从句合并5组句子。2) 写5句描述自己的城市（含从句）。3) 口头介绍城市地标。","tip":"写作想上6分必须有复合句。今天起每次写作至少放一个who/which从句。"},{"t":"交通与通勤","obj":"学会谈通勤，掌握where定语从句","time":"45分钟","v":[{"w":"traffic","m":"交通","p":"n.","e":"The traffic is terrible at rush hour."},{"w":"jam","m":"堵塞","p":"n.","e":"We were stuck in a traffic jam."},{"w":"commute","m":"通勤","p":"v./n.","e":"I commute by subway."},{"w":"subway","m":"地铁","p":"n.","e":"The subway is fast and cheap."},{"w":"rush hour","m":"高峰时段","p":"n.","e":"Avoid driving in rush hour."}],"g":{"t":"where / when 引导的定语从句","exp":"地点用where：This is the station where I get off every day. 时间用when：I remember the day when we first met. 先行词是“地点/时间”但从句缺主语宾语时仍用which/that，要分辨。","ex":["The city where I grew up has changed a lot.","I miss the days when we cycled to school.","This is the area where traffic is worst."]},"pr":"1) 用where/when定语从句写5句。2) 描述自己的通勤路线（5句）。3) 口语对比：地铁vs开车哪个更好？","tip":"描述城市的套路：总起句+地标（含从句）+交通+感受。四步走，逻辑清晰。"},{"t":"乡村生活","obj":"学会谈乡村，掌握时间状语从句","time":"45分钟","v":[{"w":"rural","m":"农村的","p":"adj.","e":"Rural life is quiet and slow."},{"w":"farm","m":"农场","p":"n.","e":"My uncle runs a small farm."},{"w":"crop","m":"庄稼","p":"n.","e":"The farmers are harvesting crops."},{"w":"field","m":"田地；领域","p":"n.","e":"Children played in the fields."},{"w":"cattle","m":"牛（总称）","p":"n.","e":"The cattle are grazing on the hill."}],"g":{"t":"时间状语从句（before / after / as soon as / until）","exp":"I will call you as soon as I arrive.（一...就...）After the harvest ends, the village gets quiet.（收获结束后）...until...（直到）：We stayed until the sun went down.","ex":["As soon as spring comes, the fields turn green.","After we finished lunch, we went for a walk.","Wait here until I come back."]},"pr":"1) 用时间状语从句写5句乡村生活。2) 写自己家乡农忙/季节变化场景。3) 口语对比：城市vs乡村，你选哪个？为什么？","tip":"城乡对比是雅思写作经典题。正反各准备3句+一个让步（Although rural life is slow...），考场上直接默写。"},{"t":"城市问题","obj":"学会谈城市问题，掌握原因状语从句","time":"45分钟","v":[{"w":"pollution","m":"污染","p":"n.","e":"Air pollution is worse in winter."},{"w":"noise","m":"噪音","p":"n.","e":"I can't sleep because of the noise."},{"w":"crowded","m":"拥挤的","p":"adj.","e":"The mall is crowded on weekends."},{"w":"crime","m":"犯罪","p":"n.","e":"Crime is low in this district."},{"w":"pressure","m":"压力","p":"n.","e":"City life brings high pressure."}],"g":{"t":"原因状语从句（because / since / as）","exp":"三个“因为”：because最直接（答Why必用）；since/as表“既然、由于”（已知原因）：Since the city is crowded, many people move out. 写作里since/as显得更成熟。","ex":["I moved out because the rent was too high.","Since traffic is heavy, I leave home early.","As houses are expensive, young people rent."]},"pr":"1) 用because/since/as各写2句谈城市问题。2) 写“城市生活的三个问题”（80词）。3) 口语讨论：大城市最大的问题是什么？","tip":"口语回答问题的黄金公式：观点+because+例子。从今天开始把它变成肌肉记忆。"},{"t":"未来城市","obj":"学会畅想未来，掌握if条件句","time":"45分钟","v":[{"w":"develop","m":"发展；开发","p":"v.","e":"The city develops very fast."},{"w":"modern","m":"现代的","p":"adj.","e":"It is a modern and green city."},{"w":"smart","m":"智能的","p":"adj.","e":"Smart cities use big data."},{"w":"sustainable","m":"可持续的","p":"adj.","e":"We need sustainable transport."},{"w":"convenient","m":"方便的","p":"adj.","e":"Life here is convenient."}],"g":{"t":"if 条件句1型（真实条件）","exp":"对将来的真实假设：If cities become smarter, life will be easier.（如果...，将会...）从句用现在时表将来，主句用will。千万别写If...will（中式英语头号错误）。","ex":["If I live in a smart city, I will save time.","If traffic gets worse, more people will cycle.","If we plant more trees, the air will be cleaner."]},"pr":"1) 用if条件句写5句未来城市畅想。2) 写80词短文《My Ideal City》。3) 口语讨论：城市会越来越好吗？","tip":"if从句用现在时表将来——这是中国人最容易错的一条。写完if句子马上检查主将从现。"}],"sun":{"t":"第16周自检：城市与乡村","obj":"检验定语从句、状语从句和条件句","pr":"1) 听写本周25词。2) 语法专项20题（定语从句+条件句）。3) 写作小练：城市vs乡村（120词，含至少2个从句）。4) 滚动复习：抽第1-15周旧词15个。","tip":"写作大作文最爱考城乡类话题。今天的对比文可以直接留作素材库。"}},{"w":17,"p":2,"theme":"环境与自然保护","d":[{"t":"环境问题","obj":"掌握环境核心词汇，初识现在完成进行时","time":"45分钟","v":[{"w":"environment","m":"环境","p":"n.","e":"We must protect the environment."},{"w":"waste","m":"浪费；废弃物","p":"v./n.","e":"Don't waste water and paper."},{"w":"recycle","m":"回收利用","p":"v.","e":"We recycle bottles and paper."},{"w":"protect","m":"保护","p":"v.","e":"Laws protect wild animals."},{"w":"pollution","m":"污染","p":"n.","e":"Plastic pollution harms the sea."}],"g":{"t":"现在完成进行时（have been doing）","exp":"从过去持续到现在的动作：I have been learning English for three months.（我学英语三个月了——还在学。）对比完成时强调结果：I have learned 500 words（结果：500词）。进行版强调“一直在”。","ex":["I have been studying English since July.","She has been working on the project all week.","We have been recycling for years."]},"pr":"1) 用完成进行时写5句（自己持续在做的事）。2) 写3句环保行动（We have been...）。3) 口语回答：How long have you been learning English?","tip":"How long have you been...?是口语考官最爱问的句式之一，答案直接秀完成进行时。"},{"t":"能源问题","obj":"学会谈能源，掌握since/for","time":"45分钟","v":[{"w":"energy","m":"能源；精力","p":"n.","e":"We should save energy at home."},{"w":"solar","m":"太阳的","p":"adj.","e":"Solar power is getting cheaper."},{"w":"wind","m":"风；风力","p":"n.","e":"Wind farms are common now."},{"w":"coal","m":"煤","p":"n.","e":"Burning coal causes smog."},{"w":"oil","m":"石油","p":"n.","e":"Oil will not last forever."}],"g":{"t":"since 与 for（持续时间的标志）","exp":"完成时/完成进行时的时间标志：since+起点（since 2020, since last week, since I was ten），for+时长（for three months, for years）。口诀：since点，for段。","ex":["I have been recycling since January.","We have used solar power for two years.","She has worked here since 2019."]},"pr":"1) 用since/for各写3句（自己坚持的环保习惯）。2) 列出家里3种节能方式（英文）。3) 口语讨论：你家怎么省电？","tip":"since和for混用是听力填空高频陷阱：听到since 2015写2020就错了，边听边记。"},{"t":"气候变化","obj":"学会谈气候变化，掌握被动语态入门","time":"45分钟","v":[{"w":"climate","m":"气候","p":"n.","e":"The climate is changing fast."},{"w":"carbon","m":"碳","p":"n.","e":"We need to cut carbon emissions."},{"w":"emission","m":"排放","p":"n.","e":"Car emissions pollute the air."},{"w":"greenhouse","m":"温室","p":"n.","e":"Greenhouse gases warm the planet."},{"w":"rise","m":"上升","p":"v./n.","e":"Sea levels are rising."}],"g":{"t":"被动语态入门（be + done）","exp":"强调动作承受者时用被动：The air is polluted by cars.（空气被汽车污染。）结构：be+过去分词。一般现在被动am/is/are done，过去被动was/were done。环保话题写作必备：The environment should be protected.","ex":["The air is polluted by factories.","Many rivers have been cleaned up.","Trees should be planted in cities."]},"pr":"1) 把5个主动句改成被动句。2) 用被动语态写5句环境问题。3) 口语讨论：气候变化是真问题吗？","tip":"写作里适当用被动显得客观学术：It is widely believed that...（人们普遍认为...）——6分写作的分水岭句型。"},{"t":"动植物保护","obj":"学会谈动植物，掌握by+施动者","time":"45分钟","v":[{"w":"wildlife","m":"野生动物","p":"n.","e":"The park protects local wildlife."},{"w":"species","m":"物种","p":"n.","e":"Many species are in danger."},{"w":"extinct","m":"灭绝的","p":"adj.","e":"Dinosaurs are extinct."},{"w":"habitat","m":"栖息地","p":"n.","e":"Forests are the habitat of tigers."},{"w":"forest","m":"森林","p":"n.","e":"Rainforests produce oxygen."}],"g":{"t":"被动语态的施动者（by...）与无施动者","exp":"被动句里动作发出者用by引出：The forest was destroyed by the fire. 不知或不必说谁做时省略：The road was built last year.（不说是谁修的。）","ex":["The habitat was destroyed by the flood.","This park was created in 1998.","Many animals are killed every year."]},"pr":"1) 写5句被动句（3句带by，2句省略）。2) 写一段“我最想保护的动物”（60词）。3) 口语讨论：动物园好不好？","tip":"动物话题是口语Part 2的常客（describe an animal you like）。被动+动保词汇组合，直接提分。"},{"t":"绿色生活","obj":"学会谈环保生活，掌握连接词让写作连贯","time":"45分钟","v":[{"w":"reusable","m":"可重复使用的","p":"adj.","e":"Bring a reusable bag when shopping."},{"w":"reduce","m":"减少","p":"v.","e":"We should reduce plastic use."},{"w":"save","m":"节省；拯救","p":"v.","e":"Save water, save the planet."},{"w":"electricity","m":"电","p":"n.","e":"Turn off lights to save electricity."},{"w":"plastic","m":"塑料","p":"n./adj.","e":"Plastic bags take years to break down."}],"g":{"t":"写作连贯性（连接词三剑客）","exp":"递进：What's more / In addition / Moreover。转折：However / Nevertheless。结果：Therefore / As a result. 环保建议文三段式：问题+建议1+递进建议2+总结呼吁，用连接词串起来。","ex":["First, we should reduce waste. Moreover, we can recycle more.","However, many people find it inconvenient.","Therefore, education is the key."]},"pr":"1) 写120词环保建议文（用上3类连接词）。2) 把自己5个日常习惯改写成“绿色版”。3) 口语讨论：个人环保有用吗？","tip":"环境是雅思写作出现率最高的话题之一，今天写的建议文留着，考到“环保类”直接升级套用。"}],"sun":{"t":"第17周自检：环境话题","obj":"检验被动语态、完成进行时和连接词","pr":"1) 听写本周25词。2) 语法专项20题（被动+完成进行时）。3) 写作小练：How can we protect the environment?（120词，含被动句2个+连接词3个）。4) 滚动复习：抽旧词15个+旧语法点复盘。","tip":"到本周你已经有了5大话题弹药库（旅行/教育/城市/环境/自我介绍）。写作和口语再也不怕没话说。"}},{"w":18,"p":2,"theme":"科技与网络","d":[{"t":"电子设备","obj":"学会谈数码设备，掌握might/may推测","time":"45分钟","v":[{"w":"device","m":"设备","p":"n.","e":"How many devices do you use daily?"},{"w":"laptop","m":"笔记本电脑","p":"n.","e":"My laptop is five years old."},{"w":"tablet","m":"平板电脑","p":"n.","e":"Kids learn on tablets now."},{"w":"smartphone","m":"智能手机","p":"n.","e":"My smartphone is my camera."},{"w":"screen","m":"屏幕","p":"n.","e":"Too much screen time is bad for eyes."}],"g":{"t":"might / may（可能性推测）","exp":"对现在的推测：He might be at home.（他可能在家。）语气不确定。对比must be（肯定）和can't be（不可能）。科技话题谈未来：AI may change everything.","ex":["She might be using the laptop now.","The battery may be dead.","This app might be useful for you."]},"pr":"1) 用might/may写5句对家人现在状态的推测。2) 写5句科技带来的可能变化。3) 口语讨论：你每天屏幕时间多长？","tip":"推测三件套：must（肯定）/ might may（可能）/ can't（不可能）。口语里用上它们立刻显得思维严谨。"},{"t":"上网活动","obj":"学会谈网络活动，掌握have to/must","time":"45分钟","v":[{"w":"browse","m":"浏览","p":"v.","e":"I browse the news in the morning."},{"w":"download","m":"下载","p":"v.","e":"I downloaded a study app."},{"w":"upload","m":"上传","p":"v.","e":"She uploads videos every week."},{"w":"search","m":"搜索","p":"v./n.","e":"Search for the word online."},{"w":"stream","m":"流媒体播放","p":"v.","e":"We stream movies at night."}],"g":{"t":"have to / must（义务的强弱）","exp":"must说话人主观“必须”：I must finish this today（我非要完成）。have to外部规则“不得不”：You have to wear a seatbelt（法律规定）。mustn't=禁止；don't have to=不必。区别巨大！","ex":["You have to pay for the app.","I must remember my passwords.","You don't have to bring your laptop."]},"pr":"1) 用have to写5句（工作/学习规则）。2) 对比造句：mustn't vs don't have to各2句。3) 口语讨论：上网时间该不该限制？","tip":"mustn't（禁止）和don't have to（不必）是考试判断题经典陷阱，今天务必分清。"},{"t":"社交软件","obj":"学会谈社交媒体，掌握could建议","time":"45分钟","v":[{"w":"app","m":"应用程序","p":"n.","e":"This app has millions of users."},{"w":"message","m":"消息；发消息","p":"n./v.","e":"Send me a message tonight."},{"w":"post","m":"发布；帖子","p":"v./n.","e":"She posts photos every day."},{"w":"share","m":"分享","p":"v./n.","e":"Share the article with friends."},{"w":"follow","m":"关注","p":"v.","e":"I follow some English teachers online."}],"g":{"t":"could / should（建议的礼貌层次）","exp":"给建议：You could try this app.（可以试试，委婉）You should try it.（应该试，更直接）You'd better...（最好...，语气最重）。礼貌排序：could < should < had better。","ex":["You could follow English accounts.","You should try online courses.","You'd better not share your password."]},"pr":"1) 用could/should/had better各写2条建议（帮朋友学好英语）。2) 写自己常用的3个app及用途。3) 口语讨论：社交媒体利大于弊吗？","tip":"建议句型三层次切换着用，口语的“词汇多样性”评分项直接受益。"},{"t":"网络安全","obj":"学会谈网络安全，掌握反身代词","time":"45分钟","v":[{"w":"password","m":"密码","p":"n.","e":"Change your password often."},{"w":"privacy","m":"隐私","p":"n.","e":"We should protect our privacy."},{"w":"hacker","m":"黑客","p":"n.","e":"Hackers steal personal information."},{"w":"account","m":"账户","p":"n.","e":"My account was hacked last year."},{"w":"protect","m":"保护","p":"v.","e":"Protect your personal information."}],"g":{"t":"反身代词（myself / yourself / himself...）","exp":"“某人自己”：I taught myself English.（我自学英语。）by myself=独自：I live by myself. 常用搭配：enjoy oneself（玩得开心），help yourself（请自便），teach oneself（自学）。","ex":["I taught myself to code.","Help yourself to some tea.","She built the website by herself."]},"pr":"1) 用反身代词写5句（自学/独自/玩得开心）。2) 写5条网络安全建议（should/could句式）。3) 口语讨论：你的信息在网上安全吗？","tip":"反身代词是听力和口语的常驻考点。尤其enjoy yourself在口语Part 1问假期时超好用。"},{"t":"科技利弊","obj":"学会辩证讨论科技，掌握both/either/neither","time":"45分钟","v":[{"w":"convenient","m":"方便的","p":"adj.","e":"Online shopping is convenient."},{"w":"addicted","m":"上瘾的","p":"adj.","e":"Many kids are addicted to games."},{"w":"face-to-face","m":"面对面的","p":"adj./adv.","e":"Face-to-face talk matters."},{"w":"distraction","m":"分心；干扰","p":"n.","e":"The phone is a big distraction."},{"w":"benefit","m":"益处；有益于","p":"n./v.","e":"Technology benefits education."}],"g":{"t":"both / either / neither（两者范围）","exp":"both...and...（两者都）：Both phones and laptops have pros. either（任一）：You can use either app. neither...nor...（两者都不）：Neither the app nor the website is safe. 辩证讨论的利器。","ex":["Both online and offline learning have benefits.","You can choose either plan.","Neither option is perfect."]},"pr":"1) 用both/either/neither写5句科技利弊。2) 写辩证段落：手机的好处与坏处（100词）。3) 口语讨论：科技让人更亲近还是更疏远？","tip":"雅思写作高分核心=辩证思维。both...and... / neither...nor...一出手，考官就知道你有两把刷子。"}],"sun":{"t":"第18周自检：科技话题","obj":"检验情态动词体系（推测/义务/建议）","pr":"1) 听写本周25词。2) 语法专项20题（might/must/have to/could）。3) 口语模拟：Describe an app you use a lot（90秒，含推测和建议句型）。4) 滚动复习：抽旧词15个。","tip":"情态动词是这三个月的语法主线之一。把它们想成“语气旋钮”：肯定→可能→禁止→建议，全在指尖。"}},{"w":19,"p":2,"theme":"媒体与新闻","d":[{"t":"新闻基础","obj":"学会新闻词汇，掌握直接引语","time":"45分钟","v":[{"w":"news","m":"新闻","p":"n.","e":"I watch the news at dinner."},{"w":"headline","m":"标题","p":"n.","e":"The headline caught my eye."},{"w":"article","m":"文章","p":"n.","e":"I read two articles every day."},{"w":"journalist","m":"记者","p":"n.","e":"The journalist interviewed the mayor."},{"w":"report","m":"报道；报告","p":"v./n.","e":"The report was published on Monday."}],"g":{"t":"直接引语（转述别人说的话）","exp":"引用原话用引号：The journalist said, \"The story is true.\" 标点规则：引号内首字母大写，say用过去式said。先会直接引语，明天升级间接引语。","ex":["She said, \"I will call you tomorrow.\"","The headline says, \"Prices are rising.\"","He asked, \"Is the news true?\""]},"pr":"1) 写5句直接引语（引用家人朋友说的话）。2) 读一篇英语新闻标题并抄写。3) 口语复述一条最近的新闻。","tip":"看英语新闻从headline开始：标题短、词汇精、语法简化，是零基础上手的最佳入口。"},{"t":"转述技巧","obj":"学会间接引语，掌握时态后移","time":"45分钟","v":[{"w":"channel","m":"频道","p":"n.","e":"I watch the news channel daily."},{"w":"program","m":"节目","p":"n.","e":"My favorite program starts at eight."},{"w":"documentary","m":"纪录片","p":"n.","e":"The documentary won a prize."},{"w":"series","m":"连续剧；系列","p":"n.","e":"We finished the series in a week."},{"w":"advertise","m":"做广告","p":"v.","e":"They advertise on social media."}],"g":{"t":"间接引语（时态后移）","exp":"转述别人话：said that+从句，时态退一步：\"I am tired\"→He said that he was tired. \"I will come\"→She said she would come. \"I have finished\"→He said he had finished. 口诀：现在→过去，将来→would，完成→过去完成。","ex":["She said that she liked the program.","He told me that he would watch the documentary.","They said they had seen the news."]},"pr":"1) 把10句直接引语改成间接引语。2) 转述家人昨天的三句话（英文）。3) 口语转述：朋友的周末安排。","tip":"间接引语是听力Section 3的隐藏考点（转述教授的话），也是写作引用观点的规范写法。"},{"t":"广告影响","obj":"学会谈广告，掌握so...that/such...that","time":"45分钟","v":[{"w":"persuade","m":"说服","p":"v.","e":"Ads persuade us to buy things."},{"w":"convince","m":"使确信","p":"v.","e":"I am convinced by the review."},{"w":"consumer","m":"消费者","p":"n.","e":"Consumers have more choices now."},{"w":"brand","m":"品牌","p":"n.","e":"Which brand do you trust?"},{"w":"commercial","m":"（电视）广告","p":"n./adj.","e":"The commercial is everywhere."}],"g":{"t":"so...that / such...that（如此...以至于）","exp":"so+形容词/副词+that：The ad is so convincing that I bought it.（广告太有说服力，我买了。）such+名词短语+that：It is such a famous brand that everyone knows it.","ex":["The ad was so funny that I shared it.","It is such a popular brand that it sells out fast.","I was so tired that I fell asleep."]},"pr":"1) 用so...that/such...that各写3句（广告/品牌话题）。2) 写“最难忘的一个广告”（60词）。3) 口语讨论：广告左右了你的选择吗？","tip":"so/such结果句是写作拉长句子的神器。6分作文和7分作文的差距常在这种细节句型上。"},{"t":"辨别信息","obj":"学会辨析事实与观点，掌握比较级进阶","time":"45分钟","v":[{"w":"fake","m":"假的","p":"adj.","e":"Fake news spreads fast online."},{"w":"truth","m":"真相","p":"n.","e":"The truth came out later."},{"w":"fact","m":"事实","p":"n.","e":"Facts can be checked."},{"w":"opinion","m":"观点","p":"n.","e":"That is just his opinion."},{"w":"believe","m":"相信","p":"v.","e":"Don't believe everything online."}],"g":{"t":"比较级与最高级进阶","exp":"构成：短词-er/-est，长词more/most。不规则：good→better→best, bad→worse→worst。比较对象：Fake news spreads faster than real news. 倍数表达：twice as fast as。最高级：the most popular app。","ex":["Fake news travels faster than real news.","This app is the most popular one.","Online news is cheaper than newspapers."]},"pr":"1) 写5句比较（传统媒体vs新媒体）。2) 改写成最高级3句。3) 口语讨论：怎么辨别假新闻？","tip":"比较级是描述图表（写作Task 1）的语言基石，现在练熟，阶段三图表作文直接起飞。"},{"t":"媒体趋势","obj":"学会谈媒体变化，综合运用被动语态","time":"45分钟","v":[{"w":"traditional","m":"传统的","p":"adj.","e":"Traditional media is losing readers."},{"w":"digital","m":"数字的","p":"adj.","e":"Digital news is instant."},{"w":"print","m":"印刷（品）","p":"v./n.","e":"Print newspapers are shrinking."},{"w":"subscribe","m":"订阅","p":"v.","e":"I subscribe to two news apps."},{"w":"platform","m":"平台","p":"n.","e":"Each platform has its style."}],"g":{"t":"被动语态综合（各时态的被动）","exp":"一般现在被动：News is published every hour. 一般过去：The story was reported last week. 现在完成：The article has been shared 10,000 times. 情态被动：Fake news should be banned. 媒体话题写作处处可用。","ex":["The newspaper was founded in 1900.","The video has been watched millions of times.","Comments should be checked before posting."]},"pr":"1) 写5句被动句（各时态各1句）。2) 写“媒体20年的变化”（100词，含3个被动句）。3) 口语讨论：你还看报纸吗？","tip":"媒体话题+被动语态是绝配：新闻都是“被报道、被分享、被转发”的。考场上这个组合拳很加分。"}],"sun":{"t":"第19周自检：媒体话题","obj":"检验间接引语、比较级和被动语态","pr":"1) 听写本周25词。2) 语法专项20题（间接引语+被动综合）。3) 口语模拟：Describe a program you enjoy watching（90秒）。4) 滚动复习：抽旧词15个。","tip":"到今天你已经能讨论相当有深度的话题了。注意积累自己的“观点句库”，口语写作都会用上。"}},{"w":20,"p":2,"theme":"运动与健康生活","d":[{"t":"运动类型","obj":"学会谈各类运动，掌握条件句0型","time":"45分钟","v":[{"w":"gym","m":"健身房","p":"n.","e":"I go to the gym after work."},{"w":"yoga","m":"瑜伽","p":"n.","e":"Yoga helps me relax."},{"w":"jogging","m":"慢跑","p":"n.","e":"Morning jogging wakes me up."},{"w":"cycling","m":"骑行","p":"n.","e":"Cycling keeps the city clean."},{"w":"workout","m":"锻炼","p":"n./v.","e":"A 30-minute workout is enough."}],"g":{"t":"条件句0型（科学规律）","exp":"表达普遍真理：If you heat ice, it melts.（加热冰就融化。）主从句都用现在时。运动版：If you exercise regularly, you feel better. 零条件=讲道理专用。","ex":["If you don't sleep, you feel tired.","If you cycle to work, you save money.","If you warm up first, you get fewer injuries."]},"pr":"1) 写5句运动与健康的规律（0条件）。2) 记录自己一周的运动计划（英文）。3) 口语讨论：什么运动适合忙碌的人？","tip":"0条件句最适合口语讲常识。它和1条件句（将来假设）双剑合璧，表达立刻有层次。"},{"t":"健身计划","obj":"学会谈健身，掌握条件句1型","time":"45分钟","v":[{"w":"coach","m":"教练","p":"n.","e":"The coach made a plan for me."},{"w":"trainer","m":"私人教练","p":"n.","e":"My trainer pushes me hard."},{"w":"equipment","m":"器材","p":"n.","e":"The gym has new equipment."},{"w":"muscle","m":"肌肉","p":"n.","e":"Exercise builds muscle."},{"w":"warm up","m":"热身","p":"phr.v.","e":"Always warm up before running."}],"g":{"t":"条件句1型复习与扩展","exp":"If + 现在时, will + 动词原形：If I go to the gym tonight, I will feel great. 健身目标版：If you keep training, you will see results in a month. 主句也可用情态：you may/can...","ex":["If you lift weights, you will build muscle.","If I finish work early, I will go jogging.","You may feel pain if you don't warm up."]},"pr":"1) 写5句自己的健身if计划。2) 写一周训练安排表（英文）。3) 口语讨论：请私教值得吗？","tip":"if句型在口语Part 3（假设类问题）出现率100%。听到If you could...开头，条件句立刻待命。"},{"t":"健康饮食","obj":"学会谈健康饮食，掌握unless","time":"45分钟","v":[{"w":"protein","m":"蛋白质","p":"n.","e":"Eggs are full of protein."},{"w":"vitamin","m":"维生素","p":"n.","e":"Fruit gives us vitamins."},{"w":"calorie","m":"卡路里","p":"n.","e":"This snack has too many calories."},{"w":"junk food","m":"垃圾食品","p":"n.","e":"Junk food is cheap but unhealthy."},{"w":"balanced","m":"均衡的","p":"adj.","e":"A balanced diet is the key."}],"g":{"t":"unless（除非）","exp":"unless = if...not：You won't lose weight unless you exercise.（不锻炼就减不了肥。）= If you don't exercise... 语气比if not更有力，写作提分词。","ex":["You won't be healthy unless you sleep well.","Unless you cook at home, you eat too much salt.","I won't go unless you come with me."]},"pr":"1) 用unless写5句健康法则。2) 写“我的一日健康食谱”（英文）。3) 口语讨论：节食能减肥吗？","tip":"unless是写作高分替换词。把作文里所有if not都换成unless，语言分立刻+0.5的既视感。"},{"t":"睡眠与减压","obj":"学会谈睡眠压力，掌握so that表目的","time":"45分钟","v":[{"w":"stay up","m":"熬夜","p":"phr.v.","e":"I never stay up late."},{"w":"asleep","m":"睡着的","p":"adj.","e":"She fell asleep on the sofa."},{"w":"relax","m":"放松","p":"v.","e":"Music helps me relax."},{"w":"stress","m":"压力","p":"n.","e":"Too much stress harms health."},{"w":"energy","m":"精力；能量","p":"n.","e":"Exercise gives me energy."}],"g":{"t":"so that（为了；以便）","exp":"表目的：I sleep early so that I can get up fresh.（早睡是为了能清爽起床。）对比in order to+动词原形（更简洁）：I sleep early in order to get up fresh. 两者可以互换。","ex":["I exercise so that I sleep better.","Save time so that you can rest.","We study English so that we can travel freely."]},"pr":"1) 用so that写5句自己的减压/作息安排。2) 把3句改成in order to。3) 口语讨论：你的减压妙招是什么？","tip":"so that和in order to交替用，写作的“语法多样性”评分点直接命中。"},{"t":"体育精神","obj":"学会谈竞争与合作，掌握as soon as","time":"45分钟","v":[{"w":"teamwork","m":"团队合作","p":"n.","e":"Teamwork beats individual skill."},{"w":"competition","m":"竞争；比赛","p":"n.","e":"The competition is next month."},{"w":"champion","m":"冠军","p":"n.","e":"She became the champion twice."},{"w":"spirit","m":"精神","p":"n.","e":"Sports build team spirit."},{"w":"defeat","m":"击败；失败","p":"v./n.","e":"Don't fear defeat."}],"g":{"t":"as soon as / the moment（一...就...）","exp":"时间紧迫感：As soon as the game started, we scored.（比赛一开始我们就进球了。）I will tell you the moment I hear the result.（一有结果我立刻告诉你。）","ex":["As soon as I get home, I will call you.","We started training the moment we decided to join.","Tell me as soon as you know."]},"pr":"1) 用as soon as写5句。2) 写“一场难忘的比赛”经历（80词）。3) 口语讨论：竞争重要还是合作重要？","tip":"运动话题可以百搭：讲经历（过去时）、讲习惯（现在时）、讲计划（将来时）、讲观点（条件句）。一个小话题，四种时态全复习。"}],"sun":{"t":"第20周自检：运动健康话题","obj":"检验条件句体系（0型/1型/unless）","pr":"1) 听写本周25词。2) 语法专项20题（条件句全家桶）。3) 写作小练：How to live a healthy life（120词，用unless和so that各1次）。4) 滚动复习：抽旧词15个。","tip":"阶段二过半。回头看看20周的语法清单，你已经从“单句时代”走到了“复合句时代”。"}},{"w":21,"p":2,"theme":"职场与职业发展","d":[{"t":"职场角色","obj":"学会职场词汇，掌握宾语从句入门","time":"45分钟","v":[{"w":"employee","m":"雇员","p":"n.","e":"The company has 200 employees."},{"w":"employer","m":"雇主","p":"n.","e":"A good employer listens."},{"w":"colleague","m":"同事","p":"n.","e":"My colleagues are supportive."},{"w":"boss","m":"上司；老板","p":"n.","e":"My boss is strict but fair."},{"w":"staff","m":"员工（总称）","p":"n.","e":"The staff meeting is at nine."}],"g":{"t":"宾语从句入门（that 可省略）","exp":"动词后接完整句子：I think (that) the meeting is useful.（我认为会议有用。）think/believe/say/hope/feel后面都能挂从句，that口语中可省。写作里挂从句=句子复杂度+1。","ex":["I think that teamwork matters most.","She said the boss was happy.","I believe remote work is the future."]},"pr":"1) 用I think/say/believe+从句写6句职场话题。2) 转述老板/同事的三句话（英文）。3) 口语讨论：好上司什么样？","tip":"口语中先用I think...开头，一边说一边组织后半句，是流利度的小技巧。"},{"t":"求职应聘","obj":"学会求职词汇，掌握whether/if宾语从句","time":"45分钟","v":[{"w":"apply","m":"申请","p":"v.","e":"I applied for the manager position."},{"w":"position","m":"职位","p":"n.","e":"The position requires teamwork."},{"w":"candidate","m":"候选人","p":"n.","e":"Three candidates passed the first round."},{"w":"vacancy","m":"空缺职位","p":"n.","e":"There is a vacancy in the sales team."},{"w":"offer","m":"录用通知；提供","p":"n./v.","e":"I got a job offer today!"}],"g":{"t":"whether / if 宾语从句（是否）","exp":"表“是否”的从句用whether/if引导：I don't know whether I should accept the offer.（我不知道该不该接受。）注意：从句用陈述语序（不是疑问语序）！固定搭配用whether：whether or not。","ex":["I am not sure if the interview went well.","She asked whether I had applied.","Do you know if the position is still open?"]},"pr":"1) 写5句“不确定”表达（whether/if从句）。2) 写一段求职经历（80词）。3) 口语模拟：为什么想换工作？","tip":"宾语从句陈述语序是中国考生头号错误：不是I don't know where is he而是where he is。今天就改过来。"},{"t":"工作技能","obj":"学会谈职业技能，掌握疑问词+不定式","time":"45分钟","v":[{"w":"communicate","m":"沟通","p":"v.","e":"We communicate by email daily."},{"w":"cooperate","m":"合作","p":"v.","e":"The two teams cooperate well."},{"w":"manage","m":"管理；应对","p":"v.","e":"She manages the whole project."},{"w":"solve","m":"解决","p":"v.","e":"We solved the problem together."},{"w":"leadership","m":"领导力","p":"n.","e":"Leadership can be learned."}],"g":{"t":"疑问词 + 不定式（how to / what to）","exp":"I don't know how to write a resume.（不知道怎么写简历。）常见的还有：what to do（做什么）、where to start（从哪开始）、whether to accept（要不要接受）。比从句简洁，口语超实用。","ex":["I don't know how to answer this question.","We are discussing where to hold the meeting.","She can't decide whether to change jobs."]},"pr":"1) 用疑问词+不定式写5句。2) 写自己的技能清单（5项+例证）。3) 口语讨论：职场最重要的技能是什么？","tip":"how to do结构是职场英语的骨架。面试里I know how to...一句话顶三句。"},{"t":"职场变动","obj":"学会谈职业变动，掌握it形式主语","time":"45分钟","v":[{"w":"promotion","m":"升职","p":"n.","e":"She got a promotion last month."},{"w":"resign","m":"辞职","p":"v.","e":"He resigned to start his own business."},{"w":"retire","m":"退休","p":"v.","e":"My father retired at sixty."},{"w":"transfer","m":"调岗；调动","p":"v./n.","e":"She was transferred to Beijing."},{"w":"raise","m":"加薪","p":"n./v.","e":"He asked the boss for a raise."}],"g":{"t":"it 形式主语（It is + adj + to do）","exp":"把真正主语放后面：It is important to communicate clearly.（清晰沟通很重要。）万能公式：It is + 形容词 + to do sth. 常配形容词：important/necessary/difficult/easy。写作从“人开头”升级到“事开头”。","ex":["It is difficult to find a good job.","It is necessary to update your skills.","It is easy to make mistakes when tired."]},"pr":"1) 用It is...to...写5句职场话题。2) 写“一次职业变动”经历（80词）。3) 口语讨论：你会为了高薪换城市吗？","tip":"it形式主语是写作万能开头：It is widely accepted that...（人们普遍认为...）六分神句。"},{"t":"工作与生活平衡","obj":"学会谈工作生活平衡，初识虚拟语气","time":"45分钟","v":[{"w":"balance","m":"平衡；余额","p":"v./n.","e":"Work-life balance matters."},{"w":"workload","m":"工作量","p":"n.","e":"My workload doubled this year."},{"w":"pressure","m":"压力","p":"n.","e":"I work well under pressure."},{"w":"flexible","m":"灵活的","p":"adj.","e":"Flexible hours help parents."},{"w":"remote","m":"远程的","p":"adj.","e":"Remote work saves two hours daily."}],"g":{"t":"suggest / recommend + 虚拟语气初步","exp":"建议句后面的从句用（should）+动词原形：I suggest that he (should) take a break.（我建议他休息。）注意不是takes！同类词：suggest, recommend, insist, demand。这是虚拟语气第一滴血。","ex":["I suggest that the company offer flexible hours.","She recommended that I apply for the job.","The doctor insists that he rest for a week."]},"pr":"1) 用suggest/recommend+虚拟语气写5条职场建议。2) 写“理想的工作状态”（100词）。3) 口语讨论：远程办公好不好？","tip":"suggest后接动词原形是高分语法点，也是易错点。写对了，考官立刻知道你学过虚拟语气。"}],"sun":{"t":"第21周自检：职场话题","obj":"检验宾语从句、形式主语和虚拟语气初步","pr":"1) 听写本周25词。2) 语法专项20题（宾语从句语序+it形式主语）。3) 口语模拟：Describe your ideal job（90秒，含宾语从句2个）。4) 滚动复习：抽旧词15个。","tip":"职场话题是雅思写作Task 2常客（工作与生活、远程办公、职业选择）。本周内容双倍重要。"}},{"w":22,"p":2,"theme":"金钱与消费","d":[{"t":"收入与支出","obj":"学会谈收支，掌握过去完成时入门","time":"45分钟","v":[{"w":"income","m":"收入","p":"n.","e":"Our income has grown this year."},{"w":"expense","m":"支出；花费","p":"n.","e":"Rent is my biggest expense."},{"w":"save","m":"储蓄；节省","p":"v.","e":"I save 20% of my salary."},{"w":"spend","m":"花费","p":"v.","e":"I spent too much online."},{"w":"budget","m":"预算","p":"n./v.","e":"We made a monthly budget."}],"g":{"t":"过去完成时（had + done）","exp":"“过去的过去”：By the time I checked, the sale had ended.（我去看时，促销已经结束了。）先发生的事用had done，后发生用过去时。标志词：by the time, before, after。","ex":["I had saved enough before I bought the car.","When I arrived, the shop had closed.","She realized she had spent all her money."]},"pr":"1) 写5句过去完成时（自己“后悔”的消费经历）。2) 做一张家庭月度英文预算表。3) 口语讨论：月光族有什么问题？","tip":"过去完成时的感觉=“来不及了”。讲遗憾经历（口语Part 2）时它自带故事感。"},{"t":"银行业务","obj":"学会银行词汇，掌握by the time","time":"45分钟","v":[{"w":"account","m":"账户","p":"n.","e":"I opened a bank account online."},{"w":"deposit","m":"存款；定金","p":"v./n.","e":"I deposit 500 yuan monthly."},{"w":"withdraw","m":"取款","p":"v.","e":"You can withdraw cash from the ATM."},{"w":"interest","m":"利息；兴趣","p":"n.","e":"The interest rate is low."},{"w":"loan","m":"贷款","p":"n.","e":"They took a loan to buy the flat."}],"g":{"t":"by the time（等到...的时候）","exp":"By the time I got to the bank, it had closed.（等我到银行时，它已经关门了。）主句多用完成时或过去时，讲“错过”专用句型。","ex":["By the time we arrived, the meeting had started.","By the time I saved enough, prices had risen.","By the time he called, I had left."]},"pr":"1) 用by the time写5句。2) 写一段“去银行办事”情景对话（10句）。3) 口语讨论：借钱给朋友好吗？","tip":"银行场景是听力Section 1-2常驻嘉宾：开户、存取、利率，今天这5个词就是入场券。"},{"t":"理财观念","obj":"学会谈理财，掌握过去完成+过去进行","time":"45分钟","v":[{"w":"invest","m":"投资","p":"v.","e":"They invest in education."},{"w":"profit","m":"利润","p":"n.","e":"The shop made a good profit."},{"w":"loss","m":"损失","p":"n.","e":"He sold the car at a loss."},{"w":"wealth","m":"财富","p":"n.","e":"Health is greater than wealth."},{"w":"manage","m":"管理","p":"v.","e":"Learn to manage money early."}],"g":{"t":"过去完成时 + 过去进行时（讲故事双引擎）","exp":"组合叙事：I had been saving for a year when the opportunity came.（机会来临时，我已经攒了一年钱。）背景用过去进行，铺垫用过去完成，事件用过去时——三层时态讲一个完整故事。","ex":["I had been working hard when the chance arrived.","She had been studying finance before she invested.","We were saving money while prices were rising."]},"pr":"1) 写一个80词的“理财小故事”（三层时态）。2) 写5条自己的理财原则。3) 口语讨论：年轻人该学投资吗？","tip":"三种时态叠加的叙事=写作和口语的双6.5配置。今天的故事结构留作Part 2模板。"},{"t":"消费观念","obj":"学会谈消费观，掌握现在完成时被动","time":"45分钟","v":[{"w":"luxury","m":"奢侈品","p":"n.","e":"I don't need luxury goods."},{"w":"necessity","m":"必需品","p":"n.","e":"Food is a necessity, not a want."},{"w":"bargain","m":"便宜货；讨价还价","p":"n./v.","e":"This bag was a real bargain."},{"w":"discount","m":"折扣","p":"n.","e":"I never pay full price without a discount."},{"w":"impulsive","m":"冲动的","p":"adj.","e":"Impulsive shopping drains money."}],"g":{"t":"现在完成时被动（have/has been done）","exp":"My card has been blocked.（我的卡被冻结了。）= 现在完成+被动。强调“已被处理”的结果。购物话题：The order has been shipped.（订单已发货。）在线购物语境超常用。","ex":["The payment has been received.","The order has been canceled.","My account has been updated."]},"pr":"1) 写5句完成时被动（购物/订单状态）。2) 写“冲动消费的一次经历”（80词）。3) 口语讨论：双十一值得囤货吗？","tip":"网购物流状态全是用完成时被动写的：shipped, delivered, refunded。听力和生活双实用。"},{"t":"金钱与幸福","obj":"学会辩证谈金钱，掌握情态动词被动","time":"45分钟","v":[{"w":"generous","m":"慷慨的","p":"adj.","e":"He is generous with friends."},{"w":"wealthy","m":"富有的","p":"adj.","e":"The wealthy also have worries."},{"w":"donate","m":"捐赠","p":"v.","e":"They donate to schools every year."},{"w":"charity","m":"慈善","p":"n.","e":"The charity helps homeless people."},{"w":"value","m":"价值；重视","p":"n./v.","e":"Health has more value than money."}],"g":{"t":"情态动词被动（should be done / can be done）","exp":"Money should be spent wisely.（钱应该被明智地花。）结构：情态动词+be+过去分词。观点句三连：...should be banned / ...can be donated / ...must be protected。写作表达“应该做某事”的升级版。","ex":["Money should be managed carefully.","Old things can be donated to charity.","Children must be taught about money."]},"pr":"1) 用情态被动写5句金钱观点。2) 写辩证短文：钱能买来幸福吗？（120词）3) 口语讨论：中彩票后会怎样？","tip":"情态被动是写作观点句的标配。本周的金句：Money is a good servant but a bad master.（钱是好的仆人，坏的主人。）"}],"sun":{"t":"第22周自检：金钱话题","obj":"检验过去完成时和各类被动语态","pr":"1) 听写本周25词。2) 语法专项20题（过去完成时+被动全家桶）。3) 写作小练：Is it good for young people to have credit cards?（120词）。4) 滚动复习：抽旧词15个。","tip":"金钱话题在雅思写作中的出镜率排前三。本周攒的观点句是考场上的硬通货。"}},{"w":23,"p":2,"theme":"文化与节日","d":[{"t":"传统节日","obj":"学会谈传统节日，掌握although让步","time":"45分钟","v":[{"w":"tradition","m":"传统","p":"n.","e":"We keep many old traditions."},{"w":"custom","m":"习俗","p":"n.","e":"The custom started long ago."},{"w":"celebrate","m":"庆祝","p":"v.","e":"We celebrate the New Year together."},{"w":"festival","m":"节日","p":"n.","e":"The festival lasts three days."},{"w":"ceremony","m":"仪式","p":"n.","e":"The ceremony begins at noon."}],"g":{"t":"although / even though（让步状语从句）","exp":"“虽然...但是...”：Although the festival is old, it is still popular.（节日虽古老，仍受欢迎。）注意：英语用了although就不能再加but！（中式英语高频错误）even though语气更强。","ex":["Although it rained, the parade went on.","Even though I live far away, I go home every year.","Although customs change, family love stays."]},"pr":"1) 用although写5句（传统与现代话题）。2) 写“我最爱的节日”介绍（100词）。3) 口语讨论：传统节日会消失吗？","tip":"although和but不共存——这是考官一眼就看到的语法错误。今天起互相检查。"},{"t":"节日活动","obj":"学会谈节日活动，掌握despite/in spite of","time":"45分钟","v":[{"w":"fireworks","m":"烟花","p":"n.","e":"The fireworks lasted an hour."},{"w":"reunion","m":"团聚","p":"n.","e":"New Year is a family reunion."},{"w":"feast","m":"盛宴","p":"n.","e":"We prepared a big feast."},{"w":"decorate","m":"装饰","p":"v.","e":"We decorate the house together."},{"w":"exchange","m":"交换","p":"v./n.","e":"We exchange gifts at midnight."}],"g":{"t":"despite / in spite of（介词版让步）","exp":"despite + 名词（不接从句！）：Despite the rain, we enjoyed the fireworks.（尽管下雨，我们还是看爽了烟花。）although+从句，despite+名词，两者是互补关系，写作交替使用显水平。","ex":["Despite the cold, everyone came out.","In spite of the noise, the baby slept.","Despite the distance, we stay close."]},"pr":"1) 用despite写5句。2) 把3句although句改成despite句。3) 口语描述：过年最难忘的场景。","tip":"despite+名词 / although+从句，一对CP各管一摊。写作里两个都出现，语法多样性满分。"},{"t":"文化差异","obj":"学会谈文化差异，掌握however/therefore","time":"45分钟","v":[{"w":"culture","m":"文化","p":"n.","e":"Culture shapes our habits."},{"w":"western","m":"西方的","p":"adj.","e":"Western festivals are popular too."},{"w":"eastern","m":"东方的","p":"adj.","e":"Eastern culture values family."},{"w":"taboo","m":"禁忌","p":"n.","e":"Learn the local taboos first."},{"w":"etiquette","m":"礼仪","p":"n.","e":"Table etiquette differs widely."}],"g":{"t":"however / therefore（连接副词）","exp":"however（然而）：Gifts show love. However, money can't replace time. therefore（因此）：Culture differs; therefore, we should learn before we travel. 注意标点：前分号或句号，后逗号。比but/so更书面。","ex":["Traditions change slowly; however, they do change.","Festivals bring family together; therefore, they matter.","Western culture is visible here. However, local customs remain strong."]},"pr":"1) 用however/therefore写5句文化对比。2) 写“中外节日对比”（120词）。3) 口语讨论：洋节该不该过？","tip":"however和therefore是写作的“高级胶水”。用对标点（分号+逗号），语法书立刻翻篇。"},{"t":"艺术欣赏","obj":"学会谈艺术形式，掌握分词作定语初步","time":"45分钟","v":[{"w":"painting","m":"绘画；画作","p":"n.","e":"The painting is 300 years old."},{"w":"sculpture","m":"雕塑","p":"n.","e":"The sculpture stands in the square."},{"w":"opera","m":"歌剧","p":"n.","e":"The opera moved me to tears."},{"w":"performance","m":"表演","p":"n.","e":"The performance was wonderful."},{"w":"exhibition","m":"展览","p":"n.","e":"The exhibition opens on Monday."}],"g":{"t":"分词作定语（the paintings made by...）","exp":"用分词短语代替定语从句更简洁：the exhibition held in Beijing（在北京办的展览）= the exhibition which was held in Beijing. 主动用-ing，被动用-ed。","ex":["The paintings drawn by children are lovely.","The songs sung at the festival are old.","The performance given last night was great."]},"pr":"1) 把5个定语从句改成分词短语。2) 写“一次看展/看演出的经历”（80词）。3) 口语讨论：艺术重要吗？","tip":"分词短语是写作字数优化器：同样的意思更少的字，还能秀语法。一举两得。"},{"t":"文化保护","obj":"学会谈文化保护，掌握whose定语从句","time":"45分钟","v":[{"w":"heritage","m":"遗产","p":"n.","e":"The city is a world heritage site."},{"w":"preserve","m":"保护；保存","p":"v.","e":"We must preserve old buildings."},{"w":"identity","m":"身份；认同","p":"n.","e":"Culture gives us identity."},{"w":"generation","m":"一代人","p":"n.","e":"Young generations love new things."},{"w":"disappear","m":"消失","p":"v.","e":"Some dialects are disappearing."}],"g":{"t":"whose 引导的定语从句","exp":"whose表“某人的”：He is a craftsman whose skills are dying out.（他是位手艺正在失传的匠人。）whose既可指人也可指物：a city whose history goes back 2,000 years.","ex":["She is an artist whose works are famous.","We visited a town whose walls are 600 years old.","The man whose house we saw is a musician."]},"pr":"1) 用whose写5句（文化人物/地点）。2) 写“濒危的文化传统”短文（100词）。3) 口语讨论：传统文化值得保护吗？","tip":"whose从句在口语Part 2描述人物时超好用：a friend whose cooking is amazing..."}],"sun":{"t":"第23周自检：文化话题","obj":"检验让步状语、连接副词和whose从句","pr":"1) 听写本周25词。2) 语法专项20题（although/despite/however）。3) 口语模拟：Describe a festival you enjoy most（90秒，用although和despite各1次）。4) 滚动复习：抽旧词15个。","tip":"文化话题是口语Part 2和写作的双料常客。本周的节日介绍文直接背下来，考谁都不怕。"}},{"w":24,"p":2,"theme":"人际关系与社会","d":[{"t":"友谊","obj":"学会谈友谊，掌握非限制性定语从句","time":"45分钟","v":[{"w":"friendship","m":"友谊","p":"n.","e":"Friendship needs time to grow."},{"w":"trust","m":"信任","p":"v./n.","e":"Good friends trust each other."},{"w":"support","m":"支持","p":"v./n.","e":"She supported me in hard times."},{"w":"share","m":"分享","p":"v.","e":"We share secrets and snacks."},{"w":"honest","m":"诚实的","p":"adj.","e":"Honest talk saves friendship."}],"g":{"t":"非限制性定语从句（, which / , who）","exp":"从句前加逗号，作补充说明：My best friend lives in Chengdu, which is famous for pandas.（我挚友住成都，那地方以熊猫闻名。）注意：非限从句不能用that引导。写作里的“信息扩展器”。","ex":["I have a best friend, who always supports me.","We met in 2015, which feels like yesterday.","He told me the truth, which surprised me."]},"pr":"1) 写5句非限制性定语从句（介绍朋友）。2) 写“我的挚友”介绍（100词）。3) 口语讨论：网友算真朋友吗？","tip":"口语介绍人物时加一个, who...补充句，流利度和复杂度双提升，考官很吃这套。"},{"t":"爱情与婚姻","obj":"学会谈婚恋话题，掌握介词+which/whom","time":"45分钟","v":[{"w":"romance","m":"浪漫；恋情","p":"n.","e":"Their romance began at work."},{"w":"couple","m":"情侣；夫妇","p":"n.","e":"The couple met in college."},{"w":"marry","m":"结婚","p":"v.","e":"They married after five years."},{"w":"divorce","m":"离婚","p":"v./n.","e":"The divorce rate is rising."},{"w":"single","m":"单身的","p":"adj.","e":"I enjoy being single now."}],"g":{"t":"介词 + which / whom（定语从句进阶）","exp":"从句谓语的介词提前：This is the cafe in which we first met.（这是我们初遇的咖啡馆。）= the cafe where we first met. 人的介词用whom：the friend with whom I travel. 正式文体专用。","ex":["The city in which they live is beautiful.","She is the colleague with whom I work most.","The day on which we met was rainy."]},"pr":"1) 把5句where/who从句改成介词+which/whom。2) 写“理想的爱情观”短文（100词）。3) 口语讨论：该不该为爱情搬家？","tip":"介词+which是写作7分的入场券。知道怎么写也要知道：口语里用where/who更自然。"},{"t":"代际关系","obj":"学会谈代沟，掌握what名词性从句","time":"45分钟","v":[{"w":"gap","m":"差距；代沟","p":"n.","e":"The generation gap is real."},{"w":"respect","m":"尊重","p":"v./n.","e":"Respect goes both ways."},{"w":"communicate","m":"沟通","p":"v.","e":"Parents and kids need to communicate."},{"w":"understand","m":"理解","p":"v.","e":"Try to understand their world."},{"w":"argue","m":"争论","p":"v.","e":"We seldom argue about big things."}],"g":{"t":"what 引导的名词性从句","exp":"what=“...的东西/事情”，引导的从句当名词用：What matters most is respect.（最重要的是尊重。）This is what I want to say.（这就是我想说的。）比that从句更灵活，口语写作双高频。","ex":["What parents need is patience.","This is what worries me.","What surprised me was his honesty."]},"pr":"1) 用What...is/are...句型写5句。2) 写“我和父母的代沟”短文（100词）。3) 口语讨论：该听父母的话吗？","tip":"What matters most is...是写作开头万能句。本周记牢，作文第一段直接用。"},{"t":"社交礼仪","obj":"学会谈礼仪，掌握强调句","time":"45分钟","v":[{"w":"polite","m":"礼貌的","p":"adj.","e":"Being polite costs nothing."},{"w":"rude","m":"粗鲁的","p":"adj.","e":"It is rude to stare."},{"w":"manner","m":"礼貌；方式","p":"n.","e":"Mind your table manners."},{"w":"greet","m":"问候；打招呼","p":"v.","e":"Greet people with a smile."},{"w":"apologize","m":"道歉","p":"v.","e":"He apologized for being late."}],"g":{"t":"强调句（It is... that...）","exp":"强调任何部分：It is respect that builds trust.（正是尊重建立了信任。）= Respect builds trust（原句）。被强调部分放It is和that之间。口语用起来立刻有力度。","ex":["It is listening that solves conflicts.","It was my mother who taught me manners.","It is honesty that matters most."]},"pr":"1) 写5句强调句（人际关系话题）。2) 把其中3句还原成普通句。3) 口语讨论：面子重要还是实话重要？","tip":"强调句=语言的聚光灯。想让考官记住哪个观点，就把它放进It is...that...里。"},{"t":"邻里社区","obj":"学会谈社区关系，掌握as方式状语从句","time":"45分钟","v":[{"w":"community","m":"社区","p":"n.","e":"Our community is friendly."},{"w":"neighborly","m":"睦邻的","p":"adj.","e":"Neighborly help is precious."},{"w":"volunteer","m":"自愿做；志愿者","p":"v./n.","e":"We volunteer to clean the park."},{"w":"harmony","m":"和谐","p":"n.","e":"Harmony makes a home."},{"w":"mutual","m":"相互的","p":"adj.","e":"Mutual help builds trust."}],"g":{"t":"as 引导的方式状语从句（正如；按照）","exp":"Do as I say.（照我说的做。）As the old saying goes, good neighbors are gold.（正如老话所说，好邻居赛金宝。）引用名言利器，口语写作一秒升级。","ex":["Do as the Romans do.","As people say, actions speak louder.","Treat others as you wish to be treated."]},"pr":"1) 用as从句写5句（引用谚语）。2) 写“我理想中的社区”（100词）。3) 口语讨论：远亲不如近邻对吗？","tip":"写作里塞一句As an old saying goes, ...，文化底蕴+语言水平同时展示，考官眼前一亮。"}],"sun":{"t":"第24周自检：人际关系话题","obj":"检验各类从句（非限定/介词+which/what/强调句）","pr":"1) 听写本周25词。2) 语法专项20题（从句全家桶）。3) 口语模拟：Describe a person who influenced you（90秒，用上强调句和what从句）。4) 滚动复习：抽旧词15个。","tip":"你已经集齐了从句的七大形态。下周起，每篇作文至少放三种从句，语法分稳了。"}},{"w":25,"p":2,"theme":"情感与心理","d":[{"t":"情绪管理","obj":"学会谈心理状态，掌握动名词不定式综合辨析","time":"45分钟","v":[{"w":"mood","m":"心情","p":"n.","e":"Music improves my mood."},{"w":"emotion","m":"情绪","p":"n.","e":"Learn to name your emotions."},{"w":"anxiety","m":"焦虑","p":"n.","e":"Exam anxiety is common."},{"w":"depression","m":"抑郁；萧条","p":"n.","e":"Talk helps with depression."},{"w":"confident","m":"自信的","p":"adj.","e":"I feel confident about the test."}],"g":{"t":"动名词 vs 不定式综合辨析","exp":"接doing：enjoy, finish, mind, keep, practice, suggest, avoid。接to do：want, decide, hope, plan, learn, agree。两者皆可（意思变）：remember/forget/stop。清单一背，写作不再错。","ex":["I enjoy talking about feelings.","She decided to see a counselor.","I avoid making decisions when angry."]},"pr":"1) 分类默写两份清单（doing/to do各7词）。2) 写5句情绪管理习惯（注意搭配）。3) 口语讨论：心情不好时你怎么办？","tip":"这周的综合辨析是语法选择题的送分点，清单值得抄在卡片上随时背。"},{"t":"压力管理","obj":"学会谈减压方法，掌握need doing","time":"45分钟","v":[{"w":"pressure","m":"压力","p":"n.","e":"Pressure can push us forward."},{"w":"cope","m":"应对（cope with）","p":"v.","e":"We all need ways to cope."},{"w":"relieve","m":"缓解","p":"v.","e":"Walking relieves my stress."},{"w":"meditate","m":"冥想","p":"v.","e":"I meditate for ten minutes daily."},{"w":"mindful","m":"正念的","p":"adj.","e":"Mindful breathing calms you."}],"g":{"t":"need doing（需要被...）","exp":"need+doing=need to be done（被动含义）：The room needs cleaning.（房间需要打扫=被打扫。）This problem needs solving.（需要被解决。）地道又高级的被动替身。","ex":["Your hair needs cutting.","The plan needs improving.","These feelings need sharing."]},"pr":"1) 用need doing写5句。2) 写“我的减压工具箱”（6条方法+原因）。3) 口语讨论：成年人的压力从哪来？","tip":"need doing是地道英语的暗号——用对了它，母语者会心一笑。"},{"t":"积极心态","obj":"学会谈积极心理，掌握worth doing","time":"45分钟","v":[{"w":"optimistic","m":"乐观的","p":"adj.","e":"Stay optimistic in hard times."},{"w":"grateful","m":"感激的","p":"adj.","e":"I am grateful for small joys."},{"w":"motivate","m":"激励","p":"v.","e":"Progress motivates me most."},{"w":"mindset","m":"心态；思维模式","p":"n.","e":"A growth mindset helps."},{"w":"achieve","m":"实现；达成","p":"v.","e":"Small steps achieve big goals."}],"g":{"t":"be worth doing（值得做）","exp":"The book is worth reading.（这书值得读。）The trip is worth planning.（旅行值得规划。）注意：worth后直接接doing，不接to do，也不用being done。","ex":["The movie is worth watching.","His advice is worth taking.","Every goal is worth working for."]},"pr":"1) 用worth doing写5句。2) 写“我今年的小成就清单”（5项）。3) 口语讨论：乐观是天生的吗？","tip":"worth doing + need doing一起用，被动语态的地道感直接拉满。"},{"t":"心理健康","obj":"学会谈心理健康，掌握感官动词结构","time":"45分钟","v":[{"w":"therapy","m":"治疗；心理治疗","p":"n.","e":"Therapy is normal self-care."},{"w":"counselor","m":"咨询师","p":"n.","e":"The counselor listens well."},{"w":"mental","m":"精神的；心理的","p":"adj.","e":"Mental health matters."},{"w":"recover","m":"恢复","p":"v.","e":"She is recovering quickly."},{"w":"wellbeing","m":"幸福；健康","p":"n.","e":"Sleep protects wellbeing."}],"g":{"t":"感官动词（see/hear/watch + sb + do/doing）","exp":"I saw her cry.（看到她哭了——全过程）I saw her crying.（看到她在哭——进行中）do表完整动作，doing表进行片段。地道英语的高频结构。","ex":["I heard him sing last night.","We watched the sun set quietly.","She felt her heart beating fast."]},"pr":"1) 用感官动词写5句。2) 写“关注心理健康”短文（100词）。3) 口语讨论：看心理咨询丢人吗？","tip":"心理健康话题近年在雅思口语写作中越来越常见，观念词汇这周一次备齐。"},{"t":"幸福话题","obj":"学会谈幸福，综合运用非谓语动词","time":"45分钟","v":[{"w":"happiness","m":"幸福","p":"n.","e":"Happiness is a skill, not luck."},{"w":"satisfy","m":"使满足","p":"v.","e":"Simple things satisfy me."},{"w":"content","m":"满足的","p":"adj.","e":"I am content with my life."},{"w":"pursue","m":"追求","p":"v.","e":"We all pursue happiness."},{"w":"meaningful","m":"有意义的","p":"adj.","e":"Meaningful work brings joy."}],"g":{"t":"非谓语动词综合（to do / doing / done 开头）","exp":"To be happy, we need friends.（目的不定式开头）Traveling alone, she found peace.（分词开头，主动=ving）Written with love, the letter moved me.（被动=ved）三种开头让句式活起来。","ex":["To stay calm, I count to ten.","Reading before bed, I relax my mind.","Given more time, I would travel."]},"pr":"1) 写3组句子（三种非谓语开头各3句）。2) 写“我的幸福观”短文（120词）。3) 口语讨论：钱和幸福的关系？","tip":"作文开头一直I think会显得幼稚。换成To be honest / To sum up，立刻成人感。"}],"sun":{"t":"第25周自检：心理话题","obj":"检验非谓语动词体系","pr":"1) 听写本周25词。2) 语法专项20题（doing/to do/worth/need doing）。3) 口语模拟：Describe something that makes you happy（90秒）。4) 滚动复习：抽旧词15个。","tip":"下周就是阶段二毕业周。把前25周的语法笔记翻一遍，给自己列一份“最常错清单”。"}},{"w":26,"p":2,"theme":"阶段二总复习与评估","d":[{"t":"时态总复习","obj":"串讲13种时态，形成完整时态地图","time":"45分钟","v":[{"w":"tense","m":"时态","p":"n.","e":"English has many tenses."},{"w":"simple","m":"一般的","p":"adj.","e":"Use the simple past for finished actions."},{"w":"continuous","m":"进行（时）","p":"adj.","e":"Continuous tenses show ongoing actions."},{"w":"perfect","m":"完成（时）","p":"adj.","e":"Perfect tenses link past and present."},{"w":"review","m":"复习","p":"v./n.","e":"Review beats new learning."}],"g":{"t":"时态全景图","exp":"阶段二学了：现在完成时（have done）、完成进行时（have been doing）、过去进行时（was doing）、过去完成时（had done）、将来时（will/be going to）。加上阶段一的三大基础时态，你已有8种时态。口诀：时态看两件事——时间和状态。","ex":["I have been learning English for six months.","I was cooking when she called.","By the time I arrived, they had left."]},"pr":"1) 做时态自测：每用时态写1句（8句）。2) 翻译10句（判断时态）。3) 在自己旧作文里找时态错误。","tip":"时态不是背出来的，是用出来的。从今天起，每次写完先做“时态三查”：统一了吗？完成时用对了吗？"},{"t":"从句与被动总复习","obj":"串讲全部从句类型和被动语态","time":"45分钟","v":[{"w":"clause","m":"从句","p":"n.","e":"Clauses make sentences rich."},{"w":"relative","m":"关系的（从句）","p":"adj.","e":"Relative clauses describe nouns."},{"w":"adverbial","m":"状语的","p":"adj.","e":"Adverbial clauses show time or reason."},{"w":"noun clause","m":"名词性从句","p":"n.","e":"Noun clauses act as objects."},{"w":"passive","m":"被动的","p":"adj.","e":"Passive voice focuses on the action."}],"g":{"t":"从句与被动全景图","exp":"已学从句：定语从句（who/which/where/when/whose/介词+which）、状语从句（时间/原因/条件/让步/目的/方式）、名词性从句（that/whether/what）。被动：一般时被动+完成时被动+情态被动。加上虚拟初步（suggest that...）。","ex":["The man who called you is my cousin.","Although it was late, we kept working.","It is believed that practice matters."]},"pr":"1) 每种从句写1句（7句）。2) 主动改被动10句。3) 给自己出5道混合语法题并解答。","tip":"语法地图已完整。以后遇到任何长难句，先找谓语动词，再分层拆从句。"},{"t":"写作综合演练","obj":"完成一篇完整的议论文","time":"50分钟","v":[{"w":"essay","m":"文章；论文","p":"n.","e":"A good essay needs structure."},{"w":"argument","m":"论点；争论","p":"n.","e":"State your argument clearly."},{"w":"example","m":"例子","p":"n.","e":"Examples make ideas real."},{"w":"conclusion","m":"结论","p":"n.","e":"The conclusion echoes the start."},{"w":"structure","m":"结构","p":"n.","e":"Structure carries ideas."}],"g":{"t":"议论文标准结构","exp":"四段式：开头（背景+立场）→ 主体段1（观点1+论据）→ 主体段2（观点2+论据或让步反驳）→ 结尾（重申+升华）。每段一个核心句+2-3个支撑句。从句+被动+连接词全用上。","ex":["It is widely believed that...","First of all, ... For example, ...","However, ... Therefore, ..."]},"pr":"限时40分钟完成作文：Some people think money brings happiness, while others disagree. Discuss both views.（250词左右）。写完自查：结构/从句/被动/连接词。","tip":"这是你的第一篇“正式”大作文。留着它，阶段四模拟周你会重写一遍，见证自己的进步。"},{"t":"听说综合演练","obj":"口语听力综合自测","time":"45分钟","v":[{"w":"fluency","m":"流利度","p":"n.","e":"Fluency grows with practice."},{"w":"pronunciation","m":"发音","p":"n.","e":"Clear pronunciation matters more."},{"w":"intonation","m":"语调","p":"n.","e":"Rising intonation asks questions."},{"w":"detail","m":"细节","p":"n.","e":"Details win listening tests."},{"w":"summary","m":"总结；摘要","p":"n./v.","e":"Summarize after listening."}],"g":{"t":"听力三步精听法","exp":"第一遍盲听抓大意；第二遍逐句暂停写关键词；第三遍对照原文找“没听出来的音”。每周精听2次，比泛听10次有效。口语同步：跟读原文，模仿语调。","ex":["Listen for numbers and dates first.","Note keywords, not full sentences.","Shadow the audio to copy intonation."]},"pr":"1) 找一段3分钟英语音频（慢速新闻/播客），做三步精听。2) 录音回答：What have you learned in the past six months?（90秒）。3) 回听自己的录音，记3个问题。","tip":"六个月前你可能连听力原文都读不顺，现在可以精听了。这就是进步的实感。"},{"t":"阶段二毕业自评","obj":"全面评估，规划阶段三","time":"45分钟","v":[{"w":"assess","m":"评估","p":"v.","e":"Assess before you plan."},{"w":"level","m":"水平；级别","p":"n.","e":"Your level is now around B1."},{"w":"target","m":"目标","p":"n./v.","e":"Keep your target in sight."},{"w":"weakness","m":"弱项","p":"n.","e":"Find your weakness early."},{"w":"strategy","m":"策略","p":"n.","e":"Strategy beats effort alone."}],"g":{"t":"阶段三预告：雅思四科技巧","exp":"阶段三（27-39周）你将进入雅思核心区：学术词汇+听力阅读策略+写作Task 1图表文+口语三部分技巧。语法只剩最后两块硬骨头：虚拟语气全家桶和倒装。B1到B2的跨越从这里开始。","ex":["IELTS has four papers.","Task 1 describes charts.","Speaking has three parts."]},"pr":"1) 自评四项（词汇/语法/听说/读写）各打分1-5。2) 写阶段三目标（3条）。3) 整理“高频错题本”前10条。","tip":"从零基础走到B1相当于爬完了半座山。接下来是山顶冲刺——学术英语和雅思技巧。"}],"sun":{"t":"阶段二毕业考：总测试","obj":"全面检验第14-26周学习成果","pr":"1) 词汇大考：本阶段325词抽50个默写（≥40合格）。2) 语法大考：综合50题（时态+从句+被动+虚拟初步）。3) 写作：限时40分钟一篇250词议论文。4) 口语：录音回答8个问题（含观点讨论题）。5) 对比阶段一毕业考：给自己写一份进步报告。","tip":"两个阶段的毕业考成绩单就是你的成长曲线图。保存好，考前冲刺周拿出来看，信心直接拉满。"}}];
